<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { actualizarFlujo, crearFlujo, listarFlujos } from '../services/flujosAtencion'
import type { FlujoAtencion } from '../interfaces/flujosAtencion.interface'
const rows=ref<FlujoAtencion[]>([]),editing=ref<FlujoAtencion|null>(null),modal=ref(false),criterio=ref(''),tipo=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref('')
const form=reactive({tipo:'',descripcion:'',activo:true})
const labels:Record<string,string>={R:'Reclamo',S:'Solicitud',SF:'Solicitud de factibilidad',SM:'Contrastación de medidor',SC:'Cambio de nombre'}
async function load(p=1){page.value=p;loading.value=true;error.value='';try{const r=await listarFlujos(criterio.value,tipo.value,p);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page}catch(e){error.value=msg(e)}finally{loading.value=false}}
function open(x?:FlujoAtencion){editing.value=x||null;Object.assign(form,{tipo:x?.tipo||'',descripcion:x?.descripcion||'',activo:x?.activo??true});modal.value=true}
async function submit(){if(!form.tipo||!form.descripcion.trim()){error.value='Complete el tipo y la descripción del flujo.';return}saving.value=true;error.value='';try{editing.value?await actualizarFlujo(editing.value.id,form):await crearFlujo(form);success.value=editing.value?'Flujo actualizado correctamente.':'Flujo registrado correctamente.';modal.value=false;await load(page.value)}catch(e){error.value=msg(e)}finally{saving.value=false}}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Comercialización / Flujos de atención</nav><header class="hero"><div class="mark">FL</div><div><small>EVAN · CONFIGURACIÓN COMERCIAL</small><h1>Flujos de atención</h1><p>Definición de procedimientos para solicitudes y reclamos.</p></div><strong>{{total}} flujos</strong><button @click="open()">+ Registrar flujo</button></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><label>Buscar<input v-model.trim="criterio" placeholder="Código o descripción" @keyup.enter="load(1)"></label><label>Tipo<select v-model="tipo"><option value="">Todos</option><option v-for="(name,key) in labels" :key="key" :value="key">{{name}}</option></select></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando flujos…</div><div v-else-if="!rows.length" class="empty">No se encontraron flujos de atención.</div><section v-else class="cards"><article v-for="x in rows" :key="x.id"><header><span>{{x.codigo}}</span><em :class="{off:!x.activo}">{{x.activo?'Activo':'Inactivo'}}</em></header><div class="icon">{{x.tipo}}</div><h2>{{x.descripcion}}</h2><p>{{labels[x.tipo]||x.tipo}}</p><dl><div><dt>Acciones</dt><dd>{{x.acciones||0}}</dd></div><div><dt>Registro</dt><dd>{{x.creado||'—'}}</dd></div></dl><footer><button @click="open(x)">Modificar</button><RouterLink :to="`/evan/comercializacion/acciones-flujo?flujo=${x.id}`">Detalle del flujo</RouterLink></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="submit"><header><div><small>FLUJO DE ATENCIÓN</small><h2>{{editing?'Modificar flujo':'Registrar nuevo flujo'}}</h2><p>El código correlativo será generado automáticamente por el sistema.</p></div><button type="button" @click="modal=false">×</button></header><label>Tipo de flujo *<select v-model="form.tipo" required><option value="">Seleccione</option><option v-for="(name,key) in labels" :key="key" :value="key">{{name}}</option></select></label><label>Descripción *<textarea v-model.trim="form.descripcion" maxlength="255" rows="4" required></textarea></label><label class="check"><input v-model="form.activo" type="checkbox"> Flujo activo y disponible para configuración</label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar flujo'}}</button></footer></form></div></div></template>
<style scoped>
.page{--a:#267bbd;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:700}.hero small,.modal small{color:var(--a);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p,.modal header p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.hero button,.filters button,.pages button,.modal footer button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.56rem}.flash{padding:10px;font-size:.63rem}.good{color:#287258;background:#edf9f3}.error{color:#a13f43;background:#fff0f0}.filters{margin-top:13px;padding:12px;display:flex;align-items:end;gap:8px;background:#fff}.filters label{flex:1;font-size:.52rem}.filters label:first-child{flex:2}input,select,textarea{width:100%;padding:9px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.58rem}.cards{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{padding:15px;border-top:3px solid var(--a);border-radius:9px;background:#fff}.cards article>header{display:flex;justify-content:space-between}.cards header span{font-size:.54rem;font-weight:700}.cards em{padding:4px 7px;border-radius:9px;color:#25775a;background:#e9f8f1;font-size:.47rem;font-style:normal}.cards em.off{color:#8a5558;background:#f7ecec}.icon{margin:13px auto;width:50px;height:50px;display:grid;place-items:center;border-radius:50%;color:#fff;background:var(--a);font-weight:700}.cards h2{min-height:34px;text-align:center;font-size:.65rem}.cards>article>p{text-align:center;color:#78858b;font-size:.51rem}.cards dl{display:grid;grid-template-columns:1fr 1fr}.cards dt{color:#89949a;font-size:.46rem}.cards dd{margin:2px 0;font-size:.51rem;font-weight:700}.cards footer{display:flex;gap:5px}.cards footer button,.cards footer a{flex:1;padding:8px;border:0;border-radius:5px;color:#fff;background:#d18c3e;text-align:center;text-decoration:none;font-size:.48rem}.cards footer a{background:#6d7183}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.6rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,650px);padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin:12px 0;font-size:.55rem}.check{display:flex!important;align-items:center;gap:7px}.check input{width:auto}.modal footer{display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}@media(max-width:800px){.cards{grid-template-columns:1fr 1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}@media(max-width:500px){.cards{grid-template-columns:1fr}}
</style>
